import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  multiTextItems = [
    {
      id: 0,
      text: ''
    }
  ];

  addItem() {
    const newItem = {
      id: this.multiTextItems.length + 1,
      text: ''
    };
    this.multiTextItems.push(newItem);
  }

  removeItem(index) {
    this.multiTextItems.splice(index, 1);
  }
}
```

### app.component.html

