      <input type="text" [(ngModel)]="item.text" name="{{i}}" />
    </label>
  </div>

  <!-- Add button -->
  <button (click)="addItem()">Add Item</button>

  <!-- Remove buttons -->
  <button (click)="removeItem(i)">Remove Item {{i}}</button>

  <!-- Display all items -->
  <ul>
    <li *ngFor="let item of multiTextItems">{{item.text}}</li>
  </ul>
