```go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/segmentio/avro-go"
)

// Define the function to read the struct definition from the Go source file.
func readStructDefinition(filename string) (interface{}, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	decoder := json.NewDecoder(file)
	var structDef interface{}
	err = decoder.Decode(&structDef)
	if err != nil {
		return nil, fmt.Errorf("failed to decode JSON: %w", err)
	}

	return structDef, nil
}

// GenerateAvroSchema converts the provided struct into an Avro schema.
func GenerateAvroSchema(structName string) ([]byte, error) {
	structDef, err := readStructDefinition(fmt.Sprintf("%s.go", structName))
	if err != nil {
		return nil, fmt.Errorf("failed to read struct definition: %w", err)
	}

	schema, err := avro.Marshal(structDef)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal struct: %w", err)
	}

	return schema, nil
}

// WriteAvroSchema writes the generated Avro schema to a file.
func WriteAvroSchema(schema []byte, filename string) error {
	f, err := os.Create(filename)
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer f.Close()

	if _, err := f.Write(schema); err != nil {
		return fmt.Errorf("failed to write to file: %w", err)
	}

	return nil
}

func main() {
	structName := "MyStruct" // Replace with the actual struct name you want to convert
	schema, err := GenerateAvroSchema(structName)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		os.Exit(1)
	}

	err = WriteAvroSchema(schema, "struct.avsc")
	if err != nil {
		fmt.Printf("Error writing Avro schema to file: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Avro schema has been successfully generated.")
}
```

### Explanation:

- **readStructDefinition**: This function opens the specified Go source file and decodes its contents as JSON. The decoded structure defines the fields and types of your struct.

- **GenerateAvroSchema**: This function takes the struct definition from the previous step and marshals it into an Avro schema using `avro.Marshal`. The resulting schema is then written to disk.

- **WriteAvroSchema**: This function creates a new file and writes the generated Avro schema to it.

- **main**: In this part of the code, we define the struct name (`MyStruct`), call the functions to generate and write the Avro schema, and print a success message if everything goes well.

### Usage:
To use this program, save the code to a file (e.g., `generate_avro_schema.go`) and run it with `go run generate_avro_schema.go`. Make sure to replace `"MyStruct"` with the actual struct name from your Go source file.

This script assumes that the struct definition includes at least field names and their corresponding types. If your struct does not have these elements, you will need to provide additional information or modify the script accordingly.

